  to authenticated using (public.is_admin('viewer'));

-- >>>>>>>>>>>>>>>>>>>> 20261113000600_stripe.sql

-- =====================================================================
-- Korea Finance Planner · migration 6 · Stripe sync functions (Phase 7)
-- All functions take/return jsonb and are callable by service_role ONLY
-- (the Edge Functions). The browser can never write billing state.
-- Edge Functions always re-fetch objects from Stripe before calling these,
-- so event order does not matter; every function is idempotent (upserts).
-- =====================================================================

-- ---------------------------------------------------------------------
-- Checkout context: everything create-checkout needs in one round trip
-- ---------------------------------------------------------------------
create or replace function public.kfp_checkout_context(p jsonb)
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select jsonb_build_object(
    'user_id',     u.id,
    'email',       u.email,
    'verified',    u.email_confirmed_at is not null,
    'legacy',      coalesce(u.email, '') ilike '%@kfp.example.com',
    'suspended',   coalesce(pr.suspended_at is not null, false),
    'price',       (select to_jsonb(pp) from public.plan_prices pp
                    where pp.active and pp.provider = 'stripe'
                      and pp.plan_id = p->>'plan' and pp.billing_interval = p->>'interval' and pp.currency = upper(p->>'currency')),
    'customer_id', (select bc.provider_customer_id from public.billing_customers bc
                    where bc.user_id = u.id and bc.provider = 'stripe'),
    'active_subscription', (select jsonb_build_object('id', s.provider_subscription_id, 'plan', s.plan_id, 'status', s.status)
                    from public.subscriptions s
                    where s.user_id = u.id and s.provider = 'stripe'
                      and s.status in ('active', 'trialing', 'past_due', 'unpaid')
                    order by s.created_at desc limit 1))
  from auth.users u
  left join public.profiles pr on pr.user_id = u.id
  where u.id = (p->>'user_id')::uuid
$$;

-- Remember the Stripe Price created for a plan_prices row (first writer wins).
create or replace function public.kfp_set_price_provider_id(p jsonb)
returns text
language plpgsql security definer
set search_path = public
as $$
declare v text;
begin
  update public.plan_prices set provider_price_id = p->>'provider_price_id'
  where id = (p->>'price_id')::uuid and provider_price_id is null;
  select provider_price_id into v from public.plan_prices where id = (p->>'price_id')::uuid;
  return v;
end;
$$;

create or replace function public.kfp_upsert_billing_customer(p jsonb)
returns void
language sql security definer
set search_path = public
as $$
  insert into public.billing_customers (user_id, provider, provider_customer_id, email)
  values ((p->>'user_id')::uuid, coalesce(p->>'provider', 'stripe'), p->>'customer_id', p->>'email')
  on conflict (user_id, provider) do update
    set provider_customer_id = excluded.provider_customer_id, email = coalesce(excluded.email, billing_customers.email)
$$;

-- user for a Stripe customer: explicit metadata first, then our mapping table
create or replace function public.kfp_user_for_customer(p_provider text, p_customer text, p_hint uuid)
returns uuid
language sql stable security definer
set search_path = public
as $$
  select coalesce(
    (select id from auth.users where id = p_hint),
    (select user_id from public.billing_customers where provider = p_provider and provider_customer_id = p_customer))
$$;

-- ---------------------------------------------------------------------
-- Subscription (checkout.session.completed, customer.subscription.*)
-- p: provider, provider_subscription_id, provider_customer_id, user_id?,
--    price_provider_id, plan_hint?, billing_interval, currency, status,
--    cancel_at_period_end, current_period_start/end, trial_end, canceled_at,
--    ended_at, unit_amount_minor, latest_invoice_id
-- ---------------------------------------------------------------------
create or replace function public.kfp_apply_subscription(p jsonb)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_provider text := coalesce(p->>'provider', 'stripe');
  v_user  uuid;
  v_price public.plan_prices;
  v_plan  text;
  v_id    uuid;
begin
  v_user := public.kfp_user_for_customer(v_provider, p->>'provider_customer_id', nullif(p->>'user_id', '')::uuid);
  if v_user is null then
    raise exception 'unknown customer %', p->>'provider_customer_id' using errcode = 'P0002';
  end if;
  if p->>'provider_customer_id' is not null then
    perform public.kfp_upsert_billing_customer(jsonb_build_object('user_id', v_user, 'provider', v_provider, 'customer_id', p->>'provider_customer_id'));
  end if;

  select * into v_price from public.plan_prices where provider = v_provider and provider_price_id = p->>'price_provider_id';
  v_plan := coalesce(v_price.plan_id, nullif(p->>'plan_hint', ''));
  if v_plan is null or not exists (select 1 from public.plans where id = v_plan) or v_plan = 'free' then
    raise exception 'cannot map price % to a plan', p->>'price_provider_id' using errcode = 'P0002';
  end if;

  insert into public.subscriptions as s (
    user_id, provider, provider_customer_id, provider_subscription_id, plan_id, price_id, billing_interval, currency,
    status, cancel_at_period_end, current_period_start, current_period_end, trial_end, canceled_at, ended_at,
    unit_amount_minor, latest_invoice_id)
  values (
    v_user, v_provider, p->>'provider_customer_id', p->>'provider_subscription_id', v_plan, v_price.id,
    p->>'billing_interval', upper(p->>'currency'), p->>'status', coalesce((p->>'cancel_at_period_end')::boolean, false),
    (p->>'current_period_start')::timestamptz, (p->>'current_period_end')::timestamptz, (p->>'trial_end')::timestamptz,
    (p->>'canceled_at')::timestamptz, (p->>'ended_at')::timestamptz, (p->>'unit_amount_minor')::bigint, p->>'latest_invoice_id')
  on conflict (provider, provider_subscription_id) where provider_subscription_id is not null do update set
    user_id = excluded.user_id, provider_customer_id = excluded.provider_customer_id, plan_id = excluded.plan_id,
    price_id = excluded.price_id, billing_interval = excluded.billing_interval, currency = excluded.currency,
    status = excluded.status, cancel_at_period_end = excluded.cancel_at_period_end,
    current_period_start = excluded.current_period_start, current_period_end = excluded.current_period_end,
    trial_end = excluded.trial_end, canceled_at = excluded.canceled_at, ended_at = excluded.ended_at,
    unit_amount_minor = excluded.unit_amount_minor, latest_invoice_id = coalesce(excluded.latest_invoice_id, s.latest_invoice_id)
  returning id into v_id;

  return jsonb_build_object('subscription_id', v_id, 'user_id', v_user, 'plan_id', v_plan, 'status', p->>'status');
end;
$$;

-- ---------------------------------------------------------------------
-- Invoice / payment (invoice.paid, invoice.payment_failed, invoice.payment_action_required)
-- p: provider, provider_invoice_id, provider_customer_id, user_id?, provider_subscription_id,
--    provider_payment_intent_id, provider_charge_id, price_provider_id, billing_interval,
--    currency, amount_due_minor, amount_paid_minor, status, failure_reason,
--    period_start, period_end, hosted_invoice_url, invoice_pdf_url, paid_at
-- A paid invoice is never downgraded by a late "failed" event, and refunds stay.
-- ---------------------------------------------------------------------
create or replace function public.kfp_apply_invoice(p jsonb)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_provider text := coalesce(p->>'provider', 'stripe');
  v_user uuid;
  v_sub  uuid;
  v_plan text;
  v_old  public.payments;
  v_status text := p->>'status';
  v_id uuid;
begin
  v_user := public.kfp_user_for_customer(v_provider, p->>'provider_customer_id', nullif(p->>'user_id', '')::uuid);
  if v_user is null then
    raise exception 'unknown customer %', p->>'provider_customer_id' using errcode = 'P0002';
  end if;
  select id into v_sub from public.subscriptions where provider = v_provider and provider_subscription_id = p->>'provider_subscription_id';
  select plan_id into v_plan from public.plan_prices where provider = v_provider and provider_price_id = p->>'price_provider_id';
  select * into v_old from public.payments where provider = v_provider and provider_invoice_id = p->>'provider_invoice_id';

  if v_old.id is not null then
    if v_old.status in ('paid', 'refunded', 'partially_refunded') and v_status in ('open', 'failed', 'action_required', 'draft') then
      v_status := v_old.status;                       -- never un-pay an invoice
    elsif v_old.amount_refunded_minor > 0 and v_status = 'paid' then
      v_status := case when v_old.amount_refunded_minor >= v_old.amount_paid_minor then 'refunded' else 'partially_refunded' end;
    end if;
  end if;

  insert into public.payments as pay (
    user_id, subscription_id, provider, provider_invoice_id, provider_payment_intent_id, provider_charge_id,
    plan_id, billing_interval, currency, amount_due_minor, amount_paid_minor, status, failure_reason,
    period_start, period_end, hosted_invoice_url, invoice_pdf_url, paid_at)
  values (
    v_user, v_sub, v_provider, p->>'provider_invoice_id', p->>'provider_payment_intent_id', p->>'provider_charge_id',
    v_plan, p->>'billing_interval', upper(p->>'currency'), coalesce((p->>'amount_due_minor')::bigint, 0),
    coalesce((p->>'amount_paid_minor')::bigint, 0), v_status, p->>'failure_reason',
    (p->>'period_start')::timestamptz, (p->>'period_end')::timestamptz, p->>'hosted_invoice_url', p->>'invoice_pdf_url',
    (p->>'paid_at')::timestamptz)
  on conflict (provider, provider_invoice_id) where provider_invoice_id is not null do update set
    user_id = excluded.user_id,
    subscription_id = coalesce(excluded.subscription_id, pay.subscription_id),
    provider_payment_intent_id = coalesce(excluded.provider_payment_intent_id, pay.provider_payment_intent_id),
    provider_charge_id = coalesce(excluded.provider_charge_id, pay.provider_charge_id),
    plan_id = coalesce(excluded.plan_id, pay.plan_id),
    billing_interval = coalesce(excluded.billing_interval, pay.billing_interval),
    amount_due_minor = excluded.amount_due_minor,
    amount_paid_minor = greatest(excluded.amount_paid_minor, pay.amount_paid_minor),
    status = v_status,
    failure_reason = case when v_status in ('failed', 'action_required') then excluded.failure_reason else pay.failure_reason end,
    period_start = coalesce(excluded.period_start, pay.period_start),
    period_end = coalesce(excluded.period_end, pay.period_end),
    hosted_invoice_url = coalesce(excluded.hosted_invoice_url, pay.hosted_invoice_url),
    invoice_pdf_url = coalesce(excluded.invoice_pdf_url, pay.invoice_pdf_url),
    paid_at = coalesce(pay.paid_at, excluded.paid_at)
  returning id into v_id;

  return jsonb_build_object('payment_id', v_id, 'user_id', v_user, 'status', v_status);
end;
$$;

-- ---------------------------------------------------------------------
-- Refunds (charge.refunded): p: provider, provider_charge_id, provider_payment_intent_id,
--   provider_invoice_id, amount_refunded_minor, currency, refunds: [{id, amount_minor, status, reason}]
-- ---------------------------------------------------------------------
create or replace function public.kfp_apply_refund(p jsonb)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_provider text := coalesce(p->>'provider', 'stripe');
  v_pay public.payments;
  r jsonb;
  v_ref bigint := coalesce((p->>'amount_refunded_minor')::bigint, 0);
begin
  select * into v_pay from public.payments
  where provider = v_provider and (
        (p->>'provider_invoice_id' is not null and provider_invoice_id = p->>'provider_invoice_id')
     or (p->>'provider_charge_id' is not null and provider_charge_id = p->>'provider_charge_id')
     or (p->>'provider_payment_intent_id' is not null and provider_payment_intent_id = p->>'provider_payment_intent_id'))
  order by created_at desc limit 1
  for update;
  if v_pay.id is null then
    raise exception 'payment for charge % not found', p->>'provider_charge_id' using errcode = 'P0002';
  end if;

  for r in select * from jsonb_array_elements(coalesce(p->'refunds', '[]'::jsonb)) loop
    insert into public.payment_refunds (payment_id, provider, provider_refund_id, amount_minor, currency, status, reason)
    values (v_pay.id, v_provider, r->>'id', (r->>'amount_minor')::bigint, upper(coalesce(p->>'currency', v_pay.currency)),
            coalesce(r->>'status', 'succeeded'), r->>'reason')
    on conflict (provider, provider_refund_id) where provider_refund_id is not null
    do update set payment_id = excluded.payment_id, status = excluded.status, amount_minor = excluded.amount_minor, reason = excluded.reason;
  end loop;

  v_ref := least(greatest(v_ref, 0), v_pay.amount_paid_minor);
  update public.payments set
    amount_refunded_minor = v_ref,
    provider_charge_id = coalesce(provider_charge_id, p->>'provider_charge_id'),
    status = case when v_ref <= 0 then status
                  when v_ref >= amount_paid_minor then 'refunded'
                  else 'partially_refunded' end
  where id = v_pay.id;
  return jsonb_build_object('payment_id', v_pay.id, 'amount_refunded_minor', v_ref);
end;
$$;

-- service_role only
do $$ declare f text; begin
  foreach f in array array[
    'kfp_checkout_context(jsonb)', 'kfp_set_price_provider_id(jsonb)', 'kfp_upsert_billing_customer(jsonb)',
    'kfp_user_for_customer(text, text, uuid)', 'kfp_apply_subscription(jsonb)', 'kfp_apply_invoice(jsonb)', 'kfp_apply_refund(jsonb)'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to service_role', f);
  end loop;
end $$;

-- >>>>>>>>>>>>>>>>>>>> 20261114000700_billing_page.sql

-- =====================================================================
-- Korea Finance Planner · migration 7 · Member billing page (Phase 8)
--   get_my_billing()      one call for account.html (only the caller's data)
--   kfp_checkout_context  + subscription details needed for cancel / resume / switch
-- Additive & re-runnable.
-- =====================================================================

create or replace function public.kfp_checkout_context(p jsonb)
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select jsonb_build_object(
    'user_id',     u.id,
    'email',       u.email,
    'verified',    u.email_confirmed_at is not null,
    'legacy',      coalesce(u.email, '') ilike '%@kfp.example.com',
    'suspended',   coalesce(pr.suspended_at is not null, false),
    'price',       (select to_jsonb(pp) from public.plan_prices pp
                    where pp.active and pp.provider = 'stripe'
                      and pp.plan_id = p->>'plan' and pp.billing_interval = p->>'interval' and pp.currency = upper(p->>'currency')),
    'customer_id', (select bc.provider_customer_id from public.billing_customers bc
                    where bc.user_id = u.id and bc.provider = 'stripe'),
    'active_subscription', (select jsonb_build_object(
                        'id', s.provider_subscription_id, 'plan', s.plan_id, 'status', s.status,
                        'cancel_at_period_end', s.cancel_at_period_end, 'billing_interval', s.billing_interval,
                        'currency', s.currency, 'current_period_end', s.current_period_end)
                    from public.subscriptions s
                    where s.user_id = u.id and s.provider = 'stripe'
                      and s.status in ('active', 'trialing', 'past_due', 'unpaid')
                    order by s.created_at desc limit 1))
  from auth.users u
  left join public.profiles pr on pr.user_id = u.id
  where u.id = (p->>'user_id')::uuid
$$;
revoke all on function public.kfp_checkout_context(jsonb) from public, anon, authenticated;
grant execute on function public.kfp_checkout_context(jsonb) to service_role;

-- Everything account.html shows, for the CALLER only.
create or replace function public.get_my_billing()
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select case when auth.uid() is null then null else jsonb_build_object(
    'entitlements', public.get_my_entitlements(),
    -- current subscription first (active/trialing/past_due/unpaid), else the most recent one
    'subscription', (
      select jsonb_build_object(
        'plan_id', s.plan_id, 'plan_name', pl.name, 'status', s.status,
        'billing_interval', s.billing_interval, 'currency', s.currency, 'unit_amount_minor', s.unit_amount_minor,
        'cancel_at_period_end', s.cancel_at_period_end, 'started_at', s.created_at,
        'current_period_start', s.current_period_start, 'current_period_end', s.current_period_end,
        'trial_end', s.trial_end, 'canceled_at', s.canceled_at, 'ended_at', s.ended_at, 'provider', s.provider)
      from public.subscriptions s join public.plans pl on pl.id = s.plan_id
      where s.user_id = auth.uid()
      order by (s.status in ('active', 'trialing', 'past_due', 'unpaid')) desc, s.created_at desc
      limit 1),
    'grants', coalesce((
      select jsonb_agg(jsonb_build_object('plan_id', e.plan_id, 'reason', e.reason, 'starts_at', e.starts_at, 'expires_at', e.expires_at)
                       order by e.expires_at nulls last)
      from public.user_entitlements e
      where e.user_id = auth.uid() and e.revoked_at is null and (e.expires_at is null or e.expires_at > now())), '[]'::jsonb),
    'has_customer', exists (select 1 from public.billing_customers b where b.user_id = auth.uid()),
    -- unpaid invoice the member can pay right now (Stripe hosted page)
    'open_invoice', (
      select jsonb_build_object('hosted_invoice_url', pm.hosted_invoice_url, 'amount_due_minor', pm.amount_due_minor,
                                'currency', pm.currency, 'status', pm.status, 'failure_reason', pm.failure_reason, 'created_at', pm.created_at)
      from public.payments pm
      where pm.user_id = auth.uid() and pm.status in ('failed', 'action_required', 'open') and pm.hosted_invoice_url is not null
      order by pm.created_at desc limit 1),
    'payments_total', (select count(*) from public.payments pm where pm.user_id = auth.uid())
  ) end
$$;
revoke all on function public.get_my_billing() from public, anon;
grant execute on function public.get_my_billing() to authenticated;

-- >>>>>>>>>>>>>>>>>>>> 20261114000800_gold_premium.sql

-- =====================================================================
-- Korea Finance Planner · migration 8 · Gold Premium Protection (Phase 9)
--
--   user_gold_data      gold portfolio (lots + settings) in its own table
--                       • NO direct insert/update/delete for browsers
--                       • SELECT only while the caller has "gold_portfolio" (RLS)
--   get_my_gold()       read  — checks Premium on every call
--   save_my_gold(...)   write — checks Premium on every call, validates input,
--                       optimistic concurrency (version) so two devices never
--                       silently overwrite each other
--   user_data           gold keys are moved out (copied first, then removed);
--                       an old cached app that still sends them is routed to
--                       user_gold_data (Premium) or ignored (no Premium)
--
-- Downgrade / expiry never deletes gold data: it stays stored and becomes
-- readable again when the member is Premium again.
-- Additive & re-runnable.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. table
-- ---------------------------------------------------------------------
create table if not exists public.user_gold_data (
  user_id     uuid primary key references auth.users(id) on delete cascade,
  lots        jsonb not null default '[]'::jsonb,
  settings    jsonb not null default '{}'::jsonb,
  version     bigint not null default 1,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint user_gold_lots_array     check (jsonb_typeof(lots) = 'array'),
  constraint user_gold_settings_obj   check (jsonb_typeof(settings) = 'object'),
  constraint user_gold_lots_max       check (jsonb_array_length(lots) <= 2000),
  constraint user_gold_size           check (pg_column_size(lots) + pg_column_size(settings) <= 1048576)
);
comment on table public.user_gold_data is
  'Gold portfolio per member. Browser access only through get_my_gold()/save_my_gold() and a Premium-gated SELECT policy.';

alter table public.user_gold_data enable row level security;
revoke all on public.user_gold_data from anon, authenticated;
grant select on public.user_gold_data to authenticated;            -- still filtered by the policy below
grant select, insert, update, delete on public.user_gold_data to service_role;

drop policy if exists user_gold_select_premium on public.user_gold_data;
create policy user_gold_select_premium on public.user_gold_data for select
  to authenticated using (auth.uid() = user_id and public.has_feature('gold_portfolio'));

-- ---------------------------------------------------------------------
-- 2. helpers
-- ---------------------------------------------------------------------
-- user_data stores raw localStorage strings: '"[{...}]"' → '[{...}]'. Bad JSON → null.
create or replace function public.kfp_parse_ls_json(v jsonb)
returns jsonb
language plpgsql immutable
set search_path = public
as $$
begin
  if v is null or jsonb_typeof(v) = 'null' then return null; end if;
  if jsonb_typeof(v) = 'string' then return (v #>> '{}')::jsonb; end if;
  return v;
exception when others then
  return null;
end;
$$;
revoke all on function public.kfp_parse_ls_json(jsonb) from public, anon, authenticated;

-- Shape check for what a browser sends. Raises 22023 (invalid_parameter_value).
create or replace function public.kfp_validate_gold(p_lots jsonb, p_settings jsonb)
returns void
language plpgsql immutable
set search_path = public
as $$
declare
  l jsonb;
begin
  if p_lots is null or jsonb_typeof(p_lots) <> 'array' then
    raise exception 'gold: lots must be an array' using errcode = '22023';
  end if;
  if jsonb_array_length(p_lots) > 2000 then
    raise exception 'gold: too many lots (max 2000)' using errcode = '22023';
  end if;
  if p_settings is null or jsonb_typeof(p_settings) <> 'object' then
    raise exception 'gold: settings must be an object' using errcode = '22023';
  end if;
  if octet_length(p_settings::text) > 16384 or octet_length(p_lots::text) > 1000000 then
    raise exception 'gold: payload too large' using errcode = '22023';
  end if;
  for l in select value from jsonb_array_elements(p_lots) loop
    -- nested IFs: SQL "or" does not short-circuit, so never cast before the type is known
    if jsonb_typeof(l) <> 'object' then
      raise exception 'gold: invalid lot' using errcode = '22023';
    end if;
    if jsonb_typeof(l->'id') is distinct from 'string' or length(l->>'id') not between 1 and 100 or octet_length(l::text) > 4096 then
      raise exception 'gold: invalid lot' using errcode = '22023';
    end if;
    if l ? 'grams' and jsonb_typeof(l->'grams') <> 'null' then
      if jsonb_typeof(l->'grams') <> 'number' then raise exception 'gold: invalid lot' using errcode = '22023'; end if;
      if (l->>'grams')::numeric < 0 then raise exception 'gold: invalid lot' using errcode = '22023'; end if;
    end if;
    if l ? 'costThb' and jsonb_typeof(l->'costThb') <> 'null' then
      if jsonb_typeof(l->'costThb') <> 'number' then raise exception 'gold: invalid lot' using errcode = '22023'; end if;
      if (l->>'costThb')::numeric < 0 then raise exception 'gold: invalid lot' using errcode = '22023'; end if;
    end if;
  end loop;
end;
$$;
revoke all on function public.kfp_validate_gold(jsonb, jsonb) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- 3. browser API (both check Premium on EVERY call)
-- ---------------------------------------------------------------------
create or replace function public.get_my_gold()
returns jsonb
language plpgsql stable security definer
set search_path = public
as $$
declare
  uid uuid := auth.uid();
  g   public.user_gold_data;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  select * into g from public.user_gold_data where user_id = uid;
  if not public.kfp_has_feature(uid, 'gold_portfolio') then
    -- No content without Premium — only whether something is kept for later.
    return jsonb_build_object('allowed', false, 'stored_lots', coalesce(jsonb_array_length(g.lots), 0));
  end if;
  return jsonb_build_object(
    'allowed',    true,
    'exists',     g.user_id is not null,
    'lots',       coalesce(g.lots, '[]'::jsonb),
    'settings',   coalesce(g.settings, '{}'::jsonb),
    'version',    coalesce(g.version, 0),
    'updated_at', g.updated_at);
end;
$$;
revoke all on function public.get_my_gold() from public, anon;
grant execute on function public.get_my_gold() to authenticated;

-- p_base_version = the version this device last saw (0 = "nothing on the server yet").
--                  null = overwrite whatever is there (member chose "keep this device").
-- Returns {ok:true, version, updated_at} or {ok:false, error:'conflict', ...server copy}.
create or replace function public.save_my_gold(p_lots jsonb, p_settings jsonb, p_base_version bigint)
returns jsonb
language plpgsql volatile security definer
set search_path = public
as $$
declare
  uid uuid := auth.uid();
  cur public.user_gold_data;
  out_row public.user_gold_data;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not public.kfp_has_feature(uid, 'gold_portfolio') then
    raise exception 'premium_required' using errcode = '42501',
      hint = 'The gold portfolio needs Finance Premium.';
  end if;
  if not public.kfp_rate_hit('gold:' || uid::text, 120, 60) then
    raise exception 'rate_limited' using errcode = '54000';
  end if;
  perform public.kfp_validate_gold(p_lots, p_settings);

  select * into cur from public.user_gold_data where user_id = uid for update;
  if p_base_version is not null and coalesce(cur.version, 0) <> p_base_version then
    return jsonb_build_object('ok', false, 'error', 'conflict',
      'version', coalesce(cur.version, 0), 'updated_at', cur.updated_at,
      'lots', coalesce(cur.lots, '[]'::jsonb), 'settings', coalesce(cur.settings, '{}'::jsonb));
  end if;
  if cur.user_id is not null and cur.lots = p_lots and cur.settings = p_settings then
    return jsonb_build_object('ok', true, 'version', cur.version, 'updated_at', cur.updated_at, 'unchanged', true);
  end if;

  insert into public.user_gold_data as g (user_id, lots, settings, version, updated_at)
  values (uid, p_lots, p_settings, 1, now())
  on conflict (user_id) do update
    set lots = excluded.lots, settings = excluded.settings, version = g.version + 1, updated_at = now()
  returning * into out_row;
  return jsonb_build_object('ok', true, 'version', out_row.version, 'updated_at', out_row.updated_at);
end;
$$;
revoke all on function public.save_my_gold(jsonb, jsonb, bigint) from public, anon;
grant execute on function public.save_my_gold(jsonb, jsonb, bigint) to authenticated;

-- ---------------------------------------------------------------------
-- 4. move existing gold out of user_data (copy first, remove only what was copied)
-- ---------------------------------------------------------------------
insert into public.user_gold_data (user_id, lots, settings, updated_at)
select d.user_id,
       case when jsonb_typeof(public.kfp_parse_ls_json(d.data->'kfp_gold_lots_v1')) = 'array'
            then public.kfp_parse_ls_json(d.data->'kfp_gold_lots_v1') else '[]'::jsonb end,
       case when jsonb_typeof(public.kfp_parse_ls_json(d.data->'kfp_gold_settings_v1')) = 'object'
            then public.kfp_parse_ls_json(d.data->'kfp_gold_settings_v1') else '{}'::jsonb end,
       coalesce(d.updated_at, now())
from public.user_data d
join auth.users u on u.id = d.user_id
where d.data ?| array['kfp_gold_lots_v1', 'kfp_gold_settings_v1']
on conflict (user_id) do nothing;

-- Only rows whose gold value could NOT be parsed keep a raw copy (nothing is ever thrown away).
create table if not exists public.user_gold_legacy_raw (
  user_id uuid primary key references auth.users(id) on delete cascade,
  raw     jsonb not null,
  saved_at timestamptz not null default now()
);
alter table public.user_gold_legacy_raw enable row level security;
revoke all on public.user_gold_legacy_raw from anon, authenticated;
grant select, insert, update, delete on public.user_gold_legacy_raw to service_role;
insert into public.user_gold_legacy_raw (user_id, raw)
select d.user_id, jsonb_build_object('kfp_gold_lots_v1', d.data->'kfp_gold_lots_v1', 'kfp_gold_settings_v1', d.data->'kfp_gold_settings_v1')
from public.user_data d
where (d.data ? 'kfp_gold_lots_v1' and jsonb_typeof(public.kfp_parse_ls_json(d.data->'kfp_gold_lots_v1')) is distinct from 'array')
   or (d.data ? 'kfp_gold_settings_v1' and jsonb_typeof(public.kfp_parse_ls_json(d.data->'kfp_gold_settings_v1')) is distinct from 'object')
on conflict (user_id) do nothing;

-- ---------------------------------------------------------------------
-- 5. user_data never stores gold again
--    (replaces the Phase 5 trigger kfp_protect_gold_keys)
-- ---------------------------------------------------------------------
create or replace function public.kfp_route_gold_keys()
returns trigger
language plpgsql security definer
set search_path = public
as $$
declare
  gold_keys text[] := array['kfp_gold_lots_v1', 'kfp_gold_settings_v1'];
  v_lots jsonb; v_settings jsonb;
  -- security definer → current_user is the owner here, so trust is decided from the JWT:
  -- service_role, or no JWT at all (SQL Editor / migrations). Browsers always carry a user JWT.
  trusted boolean := coalesce(auth.role(), '') = 'service_role' or auth.uid() is null;
begin
  if new.data is null or not (new.data ?| gold_keys) then
    return new;
  end if;
  -- An app version from before Phase 9 still sends gold inside user_data.
  -- Keep it (Premium only), in the protected table — never in user_data.
  if trusted or public.kfp_has_feature(new.user_id, 'gold_portfolio') then
    v_lots := public.kfp_parse_ls_json(new.data->'kfp_gold_lots_v1');
    v_settings := public.kfp_parse_ls_json(new.data->'kfp_gold_settings_v1');
    if jsonb_typeof(v_lots) = 'array' and jsonb_array_length(v_lots) <= 2000 then
      insert into public.user_gold_data as g (user_id, lots, settings)
      values (new.user_id, v_lots, case when jsonb_typeof(v_settings) = 'object' then v_settings else '{}'::jsonb end)
      on conflict (user_id) do update
        set lots = excluded.lots,
            settings = case when jsonb_typeof(v_settings) = 'object' then excluded.settings else g.settings end,
            version = g.version + 1, updated_at = now()
        where g.lots is distinct from excluded.lots
           or (jsonb_typeof(v_settings) = 'object' and g.settings is distinct from excluded.settings);
    end if;
  end if;
  new.data := new.data - gold_keys;
  return new;
end;
$$;
revoke all on function public.kfp_route_gold_keys() from public, anon, authenticated;

drop trigger if exists user_data_protect_gold on public.user_data;
drop trigger if exists user_data_route_gold on public.user_data;
create trigger user_data_route_gold
before insert or update on public.user_data
for each row execute procedure public.kfp_route_gold_keys();

-- strip the keys that were copied above (fires the trigger: values already identical → no new version)
update public.user_data d
set data = d.data - array['kfp_gold_lots_v1', 'kfp_gold_settings_v1']
where d.data ?| array['kfp_gold_lots_v1', 'kfp_gold_settings_v1']
  and (exists (select 1 from public.user_gold_data g where g.user_id = d.user_id)
       or exists (select 1 from public.user_gold_legacy_raw r where r.user_id = d.user_id));

-- >>>>>>>>>>>>>>>>>>>> 20261114000900_admin_dashboard.sql

-- =====================================================================
-- Korea Finance Planner · migration 9 · Admin Dashboard (Phase 10)
--
--   Read  (viewer+)  admin_whoami · admin_overview · admin_list_users · admin_user_detail
--                    admin_revenue · admin_audit_list · admin_list_prices
--   Write (admin+)   admin_set_plan · admin_extend_access · admin_revoke_access · admin_set_suspended
--                    (cancel a Stripe subscription → Edge Function admin-actions)
--
--   Every function checks the caller's role in the database (admin_roles,
--   not suspended). Every write needs a reason and writes admin_audit_logs.
--   An admin can never act on their own account, and only an owner can act
--   on another admin/owner. Nothing here deletes member data.
--
--   Scale: one set-based plan resolution for all users (no per-user calls),
--   server-side search/filter/sort/pagination (max 100 rows per page).
-- Additive & re-runnable.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 0. indexes used by the dashboard
-- ---------------------------------------------------------------------
create index if not exists profiles_created_idx      on public.profiles (created_at desc);
create index if not exists profiles_last_active_idx  on public.profiles (last_active_at desc nulls last);
create index if not exists profiles_last_login_idx   on public.profiles (last_login_at desc nulls last);
create index if not exists profiles_email_lower_idx  on public.profiles (lower(email));
create index if not exists subscriptions_user_created_idx on public.subscriptions (user_id, created_at desc);
create index if not exists payments_created_idx      on public.payments (created_at desc);
create index if not exists user_entitlements_active_idx on public.user_entitlements (user_id, expires_at) where revoked_at is null;

-- ---------------------------------------------------------------------
-- 1. role helpers
-- ---------------------------------------------------------------------
create or replace function public.kfp_admin_rank_of(p_uid uuid)
returns int
language sql stable security definer
set search_path = public
as $$
  select coalesce((
    select public.kfp_role_rank(r.role)
    from public.admin_roles r join public.profiles p on p.user_id = r.user_id
    where r.user_id = p_uid and p.suspended_at is null), 0)
$$;
revoke all on function public.kfp_admin_rank_of(uuid) from public, anon, authenticated;

-- Edge Functions (service_role) ask "what is this caller?" before acting.
create or replace function public.kfp_admin_role(p_uid uuid)
returns text
language sql stable security definer
set search_path = public
as $$
  select case public.kfp_admin_rank_of(p_uid) when 3 then 'owner' when 2 then 'admin' when 1 then 'viewer' else null end
$$;
revoke all on function public.kfp_admin_role(uuid) from public, anon, authenticated;
grant execute on function public.kfp_admin_role(uuid) to service_role;

create or replace function public.kfp_require_admin(p_min text)
returns int
language plpgsql stable security definer
set search_path = public
as $$
declare r int;
begin
  r := case when auth.uid() is null then 0 else public.kfp_admin_rank_of(auth.uid()) end;
  if r < public.kfp_role_rank(p_min) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  return r;
end;
$$;
revoke all on function public.kfp_require_admin(text) from public, anon, authenticated;

-- self-protection + hierarchy for every write
create or replace function public.kfp_guard_target(p_target uuid, p_caller uuid, p_reason text)
returns void
language plpgsql stable security definer
set search_path = public
as $$
begin
  if p_target is null or not exists (select 1 from auth.users where id = p_target) then
    raise exception 'user_not_found' using errcode = 'P0002';
  end if;
  if p_target = p_caller then
    raise exception 'cannot_act_on_self' using errcode = '42501';
  end if;
  if public.kfp_admin_rank_of(p_target) > 0 and public.kfp_admin_rank_of(p_caller) < 3 then
    raise exception 'only_owner_can_change_admins' using errcode = '42501';
  end if;
  if coalesce(length(trim(p_reason)), 0) < 3 or length(p_reason) > 500 then
    raise exception 'reason_required' using errcode = '22023';
  end if;
end;
$$;
revoke all on function public.kfp_guard_target(uuid, uuid, text) from public, anon, authenticated;

create or replace function public.kfp_activity_bucket(p_last timestamptz)
returns text
language sql stable
as $$
  select case when p_last is null then 'never'
              when p_last > now() - interval '24 hours' then 'active'
              when p_last > now() - interval '7 days'   then 'recent'
              when p_last > now() - interval '30 days'  then 'inactive'
              else 'dormant' end
$$;

-- ---------------------------------------------------------------------
-- 2. effective plan for ALL users in one query
--    Same rules as kfp_effective_plan(uid) (tests compare both for every user).
-- ---------------------------------------------------------------------
create or replace function public.kfp_effective_plans_all()
returns table (user_id uuid, plan_id text, source text, status text, valid_until timestamptz)
language sql stable security definer
set search_path = public
as $$
  with cand as (
    select s.user_id, s.plan_id, ('subscription:' || s.provider)::text as source, s.status,
           case when s.status = 'past_due'
                then s.current_period_start + make_interval(days => coalesce((p.limits->>'grace_days')::int, 0))
                else s.current_period_end end as valid_until
    from public.subscriptions s
    join public.plans p on p.id = s.plan_id
    where (s.status in ('active','trialing') and (s.current_period_end is null or s.current_period_end > now()))
       or (s.status = 'past_due' and s.current_period_start is not null
           and now() < s.current_period_start + make_interval(days => coalesce((p.limits->>'grace_days')::int, 0)))
    union all
    select e.user_id, e.plan_id, e.reason, 'granted', e.expires_at
    from public.user_entitlements e
    where e.revoked_at is null and e.starts_at <= now() and (e.expires_at is null or e.expires_at > now())
  ),
  ranked as (
    select c.*, row_number() over (partition by c.user_id order by p.sort desc, c.valid_until desc nulls first) as rn
    from cand c join public.plans p on p.id = c.plan_id
    where p.active
  )
  select u.id,
         case when pr.suspended_at is not null or r.user_id is null then 'free' else r.plan_id end,
         case when pr.suspended_at is not null then 'suspended' when r.user_id is null then 'default' else r.source end,
         case when pr.suspended_at is not null or r.user_id is null then 'none' else r.status end,
         case when pr.suspended_at is not null then null else r.valid_until end
  from auth.users u
  left join public.profiles pr on pr.user_id = u.id
  left join ranked r on r.user_id = u.id and r.rn = 1
$$;
revoke all on function public.kfp_effective_plans_all() from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- 3. read API (viewer+)
-- ---------------------------------------------------------------------
create or replace function public.admin_whoami()
returns jsonb
language plpgsql stable security definer
set search_path = public
as $$
declare r int := public.kfp_require_admin('viewer');
begin
  return jsonb_build_object('user_id', auth.uid(),
    'role', case r when 3 then 'owner' when 2 then 'admin' else 'viewer' end,
    'can_write', r >= 2, 'is_owner', r >= 3);
end;
$$;
revoke all on function public.admin_whoami() from public, anon;
grant execute on function public.admin_whoami() to authenticated;

-- monthly recurring amount of one subscription row, in its currency's minor unit
create or replace function public.kfp_monthly_minor(p_amount bigint, p_interval text)
returns numeric
language sql immutable
as $$ select case when p_amount is null then 0 when p_interval = 'year' then p_amount / 12.0 else p_amount::numeric end $$;

create or replace function public.admin_overview(p_tz text default 'Asia/Seoul')
returns jsonb
language plpgsql stable security definer
set search_path = public
set jit = off                                    -- one-row reports: JIT compile time (seconds) >> run time (ms)
as $$
declare
  tz text := case when exists (select 1 from pg_timezone_names where name = p_tz) then p_tz else 'Asia/Seoul' end;
  today_start timestamptz := date_trunc('day', now() at time zone tz) at time zone tz;
  month_start timestamptz := date_trunc('month', now() at time zone tz) at time zone tz;
  v_out jsonb;
begin
  perform public.kfp_require_admin('viewer');
  with plans_now as (select * from public.kfp_effective_plans_all()),
  latest as (                                  -- one "current" subscription per user (live first)
    select distinct on (s.user_id) s.*
    from public.subscriptions s
    order by s.user_id, (s.status in ('active','trialing','past_due','unpaid')) desc, s.created_at desc
  ),
  live as (select * from public.subscriptions where status in ('active', 'past_due')),   -- paying (past_due = still billed)
  mrr as (
    select currency, round(sum(public.kfp_monthly_minor(unit_amount_minor, billing_interval)))::bigint as mrr_minor, count(distinct user_id) as payers
    from live group by currency
  ),
  churn as (
    select count(*) filter (where s.ended_at > now() - interval '30 days' or (s.status = 'canceled' and s.canceled_at > now() - interval '30 days')) as churned
    from public.subscriptions s
  ),
  rev as (
    select currency,
           sum(amount_paid_minor) as gross_minor,
           sum(amount_refunded_minor) as refunded_minor,
           sum(amount_paid_minor) filter (where coalesce(paid_at, created_at) > now() - interval '30 days') as gross_30d_minor
    from public.payments where status in ('paid', 'partially_refunded', 'refunded') group by currency
  )
  select jsonb_build_object(
    'tz', tz, 'generated_at', now(),
    'users', jsonb_build_object(
      'total',      (select count(*) from auth.users),
      'new_today',  (select count(*) from auth.users where created_at >= today_start),
      'new_month',  (select count(*) from auth.users where created_at >= month_start),
      'suspended',  (select count(*) from public.profiles where suspended_at is not null),
      'unverified', (select count(*) from auth.users where email_confirmed_at is null)),
    'plans', jsonb_build_object(
      'free',    (select count(*) from plans_now where plan_id = 'free'),
      'plus',    (select count(*) from plans_now where plan_id = 'plus'),
      'premium', (select count(*) from plans_now where plan_id = 'premium'),
      'via_subscription', (select count(*) from plans_now where source like 'subscription:%'),
      'via_grant',        (select count(*) from plans_now where plan_id <> 'free' and source not like 'subscription:%')),
    'subscriptions', jsonb_build_object(
      'active',     (select count(*) from latest where status = 'active' and not cancel_at_period_end),
      'trialing',   (select count(*) from latest where status = 'trialing'),
      'cancelling', (select count(*) from latest where status in ('active','trialing') and cancel_at_period_end),
      'past_due',   (select count(*) from latest where status in ('past_due', 'unpaid')),
      'expired',    (select count(*) from latest where status in ('canceled', 'incomplete_expired') or (status in ('active','trialing') and current_period_end < now()))),
    'activity', (select jsonb_object_agg(b, n) from (
        select public.kfp_activity_bucket(last_active_at) as b, count(*) as n from public.profiles group by 1) a),
    'mrr', coalesce((select jsonb_object_agg(currency, jsonb_build_object(
                'mrr_minor', mrr_minor, 'arr_minor', mrr_minor * 12, 'payers', payers,
                'arpu_minor', case when payers > 0 then round(mrr_minor::numeric / payers)::bigint else 0 end))
              from mrr where currency is not null), '{}'::jsonb),
    'revenue', coalesce((select jsonb_object_agg(currency, jsonb_build_object(
                'gross_minor', gross_minor, 'refunded_minor', refunded_minor, 'net_minor', gross_minor - refunded_minor,
                'gross_30d_minor', coalesce(gross_30d_minor, 0)))
              from rev where currency is not null), '{}'::jsonb),
    'churn_30d', (select jsonb_build_object(
                'churned', churned,
                'base', churned + (select count(*) from public.subscriptions where status in ('active','trialing','past_due')),
                'rate_pct', case when churned + (select count(*) from public.subscriptions where status in ('active','trialing','past_due')) = 0 then 0
                                 else round(100.0 * churned / (churned + (select count(*) from public.subscriptions where status in ('active','trialing','past_due'))), 2) end)
              from churn),
    'failed_payments_30d', (select count(*) from public.payments where status in ('failed','action_required') and created_at > now() - interval '30 days'),
    'webhooks_failed', (select count(*) from public.stripe_webhook_events where status = 'failed')
  ) into v_out;
  return v_out;
end;
$$;
revoke all on function public.admin_overview(text) from public, anon;
grant execute on function public.admin_overview(text) to authenticated;

-- p: {q, plan, sub_status, activity, country, suspended, sort, dir, page, page_size}
create or replace function public.admin_list_users(p jsonb default '{}'::jsonb)
returns jsonb
language plpgsql stable security definer
set search_path = public
set jit = off                                    -- one-row reports: JIT compile time (seconds) >> run time (ms)
as $$
declare
  v_q    text := nullif(trim(coalesce(p->>'q', '')), '');
  v_like text;
  v_plan text := nullif(p->>'plan', '');
  v_st   text := nullif(p->>'sub_status', '');
  v_act  text := nullif(p->>'activity', '');
  v_cty  text := nullif(upper(p->>'country'), '');
  v_susp boolean := case p->>'suspended' when 'true' then true when 'false' then false else null end;
  v_sort text := coalesce(nullif(p->>'sort', ''), 'created_at');
  v_desc boolean := coalesce(p->>'dir', 'desc') <> 'asc';
  v_size int := least(greatest(coalesce((p->>'page_size')::int, 25), 5), 100);
  v_page int := greatest(coalesce((p->>'page')::int, 1), 1);
  v_out jsonb;
begin
  perform public.kfp_require_admin('viewer');
  if v_sort not in ('created_at', 'last_active_at', 'last_login_at', 'email', 'expires_at', 'plan') then v_sort := 'created_at'; end if;
  if v_q is not null then
    v_q := left(v_q, 100);
    v_like := '%' || replace(replace(replace(lower(v_q), '\', '\\'), '%', '\%'), '_', '\_') || '%';
  end if;

  with base as (
    select u.id as user_id, coalesce(pr.email, u.email) as email, pr.username, pr.nickname, pr.country,
           u.created_at, pr.last_login_at, pr.last_active_at, pr.last_page, pr.suspended_at, u.email_confirmed_at,
           e.plan_id, e.source as plan_source, e.valid_until,
           ls.status as sub_status, ls.cancel_at_period_end, ls.created_at as sub_started_at, ls.current_period_end,
           ls.currency as sub_currency, ls.billing_interval, ls.provider_subscription_id,
           coalesce(e.valid_until, case when ls.status in ('active','trialing') then ls.current_period_end end) as expires_at,
           public.kfp_activity_bucket(pr.last_active_at) as activity,
           (ar.user_id is not null) as is_admin
    from auth.users u
    left join public.profiles pr on pr.user_id = u.id
    left join public.admin_roles ar on ar.user_id = u.id
    join public.kfp_effective_plans_all() e on e.user_id = u.id
    left join lateral (
      select s.* from public.subscriptions s where s.user_id = u.id
      order by (s.status in ('active','trialing','past_due','unpaid')) desc, s.created_at desc limit 1) ls on true
    where (v_q is null
           or lower(coalesce(pr.email, u.email, '')) like v_like escape '\'
           or lower(coalesce(pr.username, '')) like v_like escape '\'
           or lower(coalesce(pr.nickname, '')) like v_like escape '\'
           or u.id::text = lower(v_q))
  ),
  filtered as (
    select b.*, count(*) over () as total from base b
    where (v_plan is null or b.plan_id = v_plan)
      and (v_act  is null or b.activity = v_act)
      and (v_cty  is null or upper(coalesce(b.country, '')) = v_cty)
      and (v_susp is null or (b.suspended_at is not null) = v_susp)
      and (v_st is null
           or (v_st = 'none'       and b.sub_status is null)
           or (v_st = 'cancelling' and b.sub_status in ('active','trialing') and b.cancel_at_period_end)
           or (v_st = 'active'     and b.sub_status = 'active' and not b.cancel_at_period_end)
           or (v_st = 'past_due'   and b.sub_status in ('past_due','unpaid'))
           or (v_st = 'canceled'   and b.sub_status in ('canceled','incomplete_expired'))
           or (v_st not in ('none','cancelling','active','past_due','canceled') and b.sub_status = v_st))
  ),
  page as (
    select * from filtered
    order by
      case when not v_desc and v_sort = 'created_at'     then created_at end asc,
      case when     v_desc and v_sort = 'created_at'     then created_at end desc,
      case when not v_desc and v_sort = 'last_active_at' then last_active_at end asc nulls last,
      case when     v_desc and v_sort = 'last_active_at' then last_active_at end desc nulls last,
      case when not v_desc and v_sort = 'last_login_at'  then last_login_at end asc nulls last,
      case when     v_desc and v_sort = 'last_login_at'  then last_login_at end desc nulls last,
      case when not v_desc and v_sort = 'email'          then lower(email) end asc,
      case when     v_desc and v_sort = 'email'          then lower(email) end desc,
      case when not v_desc and v_sort = 'expires_at'     then expires_at end asc nulls last,
      case when     v_desc and v_sort = 'expires_at'     then expires_at end desc nulls last,
      case when not v_desc and v_sort = 'plan'           then (select sort from public.plans where id = plan_id) end asc,
      case when     v_desc and v_sort = 'plan'           then (select sort from public.plans where id = plan_id) end desc,
      created_at desc, user_id
    limit v_size offset (v_page - 1) * v_size
  )
  select jsonb_build_object(
    'page', v_page, 'page_size', v_size,
    'total', coalesce((select total from filtered limit 1), 0),
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
        'user_id', user_id, 'email', email, 'username', username, 'country', country,
        'plan', plan_id, 'plan_source', plan_source, 'sub_status', sub_status, 'cancel_at_period_end', cancel_at_period_end,
        'registered_at', created_at, 'sub_started_at', sub_started_at, 'expires_at', expires_at,
        'last_login_at', last_login_at, 'last_active_at', last_active_at, 'last_page', last_page,
        'days_since_active', case when last_active_at is null then null else floor(extract(epoch from now() - last_active_at) / 86400)::int end,
        'activity', activity, 'suspended', suspended_at is not null, 'verified', email_confirmed_at is not null,
        'is_admin', is_admin)) from page), '[]'::jsonb)
  ) into v_out;
  return v_out;
end;
$$;
revoke all on function public.admin_list_users(jsonb) from public, anon;
grant execute on function public.admin_list_users(jsonb) to authenticated;

create or replace function public.admin_user_detail(p_user uuid)
returns jsonb
language plpgsql stable security definer
set search_path = public
set jit = off                                    -- one-row reports: JIT compile time (seconds) >> run time (ms)
as $$
declare v_out jsonb;
begin
  perform public.kfp_require_admin('viewer');
  if not exists (select 1 from auth.users where id = p_user) then
    raise exception 'user_not_found' using errcode = 'P0002';
  end if;
  select jsonb_build_object(
    'user', (select jsonb_build_object(
        'user_id', u.id, 'email', coalesce(pr.email, u.email), 'username', pr.username, 'nickname', pr.nickname,
        'country', pr.country, 'registered_at', u.created_at, 'verified_at', u.email_confirmed_at,
        'legacy_email', coalesce(pr.is_legacy_email, false), 'last_login_at', pr.last_login_at,
        'last_active_at', pr.last_active_at, 'last_page', pr.last_page, 'suspended_at', pr.suspended_at,
        'activity', public.kfp_activity_bucket(pr.last_active_at),
        'admin_role', public.kfp_admin_role(u.id))
      from auth.users u left join public.profiles pr on pr.user_id = u.id where u.id = p_user),
    'effective', (select to_jsonb(e) from public.kfp_effective_plan(p_user) e limit 1),
    'customer', (select jsonb_build_object('provider', b.provider, 'customer_id', b.provider_customer_id, 'email', b.email)
                 from public.billing_customers b where b.user_id = p_user limit 1),
    'subscriptions', coalesce((select jsonb_agg(jsonb_build_object(
        'id', s.id, 'provider', s.provider, 'provider_subscription_id', s.provider_subscription_id,
        'plan_id', s.plan_id, 'status', s.status, 'billing_interval', s.billing_interval, 'currency', s.currency,
        'unit_amount_minor', s.unit_amount_minor, 'cancel_at_period_end', s.cancel_at_period_end,
        'started_at', s.created_at, 'current_period_start', s.current_period_start, 'current_period_end', s.current_period_end,
        'canceled_at', s.canceled_at, 'ended_at', s.ended_at) order by s.created_at desc)
      from public.subscriptions s where s.user_id = p_user), '[]'::jsonb),
    'entitlements', coalesce((select jsonb_agg(jsonb_build_object(
        'id', e.id, 'plan_id', e.plan_id, 'reason', e.reason, 'note', e.note, 'starts_at', e.starts_at, 'expires_at', e.expires_at,
        'revoked_at', e.revoked_at, 'active', e.revoked_at is null and e.starts_at <= now() and (e.expires_at is null or e.expires_at > now()),
        'granted_by', (select email from public.profiles where user_id = e.granted_by)) order by e.created_at desc)
      from public.user_entitlements e where e.user_id = p_user), '[]'::jsonb),
    'payments', coalesce((select jsonb_agg(x order by x->>'created_at' desc) from (
        select jsonb_build_object('id', pm.id, 'provider_invoice_id', pm.provider_invoice_id, 'plan_id', pm.plan_id,
          'billing_interval', pm.billing_interval, 'currency', pm.currency, 'amount_due_minor', pm.amount_due_minor,
          'amount_paid_minor', pm.amount_paid_minor, 'amount_refunded_minor', pm.amount_refunded_minor, 'status', pm.status,
          'failure_reason', pm.failure_reason, 'hosted_invoice_url', pm.hosted_invoice_url, 'invoice_pdf_url', pm.invoice_pdf_url,
          'paid_at', pm.paid_at, 'created_at', pm.created_at) as x
        from public.payments pm where pm.user_id = p_user order by pm.created_at desc limit 50) t), '[]'::jsonb),
    'payments_total', (select count(*) from public.payments where user_id = p_user),
    'activity', coalesce((select jsonb_agg(x order by x->>'at' desc) from (
        select jsonb_build_object('kind', a.kind, 'page', a.page, 'at', a.created_at) as x
        from public.user_activity a where a.user_id = p_user order by a.created_at desc limit 50) t), '[]'::jsonb),
    'audit', coalesce((select jsonb_agg(x order by (x->>'id')::bigint desc) from (
        select jsonb_build_object('id', l.id, 'action', l.action, 'reason', l.reason, 'at', l.created_at,
          'admin', (select email from public.profiles where user_id = l.admin_id), 'after', l.after) as x
        from public.admin_audit_logs l where l.target_user_id = p_user order by l.id desc limit 30) t), '[]'::jsonb),
    'gold_lots', (select jsonb_array_length(g.lots) from public.user_gold_data g where g.user_id = p_user)
  ) into v_out;
  return v_out;
end;
$$;
revoke all on function public.admin_user_detail(uuid) from public, anon;
grant execute on function public.admin_user_detail(uuid) to authenticated;

-- p: {months (1..36, default 12), tz}
create or replace function public.admin_revenue(p jsonb default '{}'::jsonb)
returns jsonb
language plpgsql stable security definer
set search_path = public
set jit = off                                    -- one-row reports: JIT compile time (seconds) >> run time (ms)
as $$
declare
  v_months int := least(greatest(coalesce((p->>'months')::int, 12), 1), 36);
  tz text := case when exists (select 1 from pg_timezone_names where name = p->>'tz') then p->>'tz' else 'Asia/Seoul' end;
  v_from timestamptz := date_trunc('month', (now() at time zone tz) - make_interval(months => v_months - 1)) at time zone tz;
  v_out jsonb;
begin
  perform public.kfp_require_admin('viewer');
  with paid as (
    select * from public.payments where status in ('paid', 'partially_refunded', 'refunded')
  ),
  live as (select * from public.subscriptions where status in ('active', 'past_due'))
  select jsonb_build_object(
    'tz', tz, 'from', v_from,
    'by_currency', coalesce((select jsonb_object_agg(c, x) from (
        select cur.c, jsonb_build_object(
          'gross_minor',    coalesce((select sum(amount_paid_minor) from paid where currency = cur.c), 0),
          'refunded_minor', coalesce((select sum(amount_refunded_minor) from paid where currency = cur.c), 0),
          'net_minor',      coalesce((select sum(amount_paid_minor - amount_refunded_minor) from paid where currency = cur.c), 0),
          'period_gross_minor', coalesce((select sum(amount_paid_minor) from paid where currency = cur.c and coalesce(paid_at, created_at) >= v_from), 0),
          'period_net_minor',   coalesce((select sum(amount_paid_minor - amount_refunded_minor) from paid where currency = cur.c and coalesce(paid_at, created_at) >= v_from), 0),
          'mrr_minor', coalesce((select round(sum(public.kfp_monthly_minor(unit_amount_minor, billing_interval)))::bigint from live where currency = cur.c), 0),
          'arr_minor', coalesce((select round(sum(public.kfp_monthly_minor(unit_amount_minor, billing_interval)) * 12)::bigint from live where currency = cur.c), 0),
          'payers', (select count(distinct user_id) from live where currency = cur.c)) as x
        from (select distinct currency as c from public.payments union select distinct currency from public.subscriptions where currency is not null) cur
        where cur.c is not null) t), '{}'::jsonb),
    'by_plan', coalesce((select jsonb_agg(x order by x->>'currency', x->>'plan_id') from (
        select jsonb_build_object('plan_id', pl.plan_id, 'currency', pl.currency,
          'subscribers', (select count(*) from live l where l.plan_id = pl.plan_id and l.currency = pl.currency),
          'mrr_minor', coalesce((select round(sum(public.kfp_monthly_minor(unit_amount_minor, billing_interval)))::bigint from live l where l.plan_id = pl.plan_id and l.currency = pl.currency), 0),
          'gross_minor', coalesce((select sum(amount_paid_minor) from paid pd where pd.plan_id = pl.plan_id and pd.currency = pl.currency), 0),
          'net_minor', coalesce((select sum(amount_paid_minor - amount_refunded_minor) from paid pd where pd.plan_id = pl.plan_id and pd.currency = pl.currency), 0)) as x
        from (select distinct plan_id, currency from paid where plan_id is not null
              union select distinct plan_id, currency from live where currency is not null) pl) t), '[]'::jsonb),
    'monthly', coalesce((select jsonb_agg(jsonb_build_object('month', m, 'currency', currency, 'gross_minor', g, 'refunded_minor', r,
          'net_minor', g - r, 'payments', n) order by m, currency) from (
        select to_char(coalesce(paid_at, created_at) at time zone tz, 'YYYY-MM') as m, currency,
               sum(amount_paid_minor) as g, sum(amount_refunded_minor) as r, count(*) as n
        from paid where coalesce(paid_at, created_at) >= v_from group by 1, 2) t), '[]'::jsonb),
    'failed', jsonb_build_object(
        'count_30d', (select count(*) from public.payments where status in ('failed','action_required') and created_at > now() - interval '30 days'),
        'latest', coalesce((select jsonb_agg(x order by x->>'created_at' desc) from (
          select jsonb_build_object('user_id', pm.user_id, 'email', pr.email, 'currency', pm.currency, 'amount_due_minor', pm.amount_due_minor,
            'status', pm.status, 'failure_reason', pm.failure_reason, 'created_at', pm.created_at, 'hosted_invoice_url', pm.hosted_invoice_url) as x
          from public.payments pm left join public.profiles pr on pr.user_id = pm.user_id
          where pm.status in ('failed','action_required','uncollectible') order by pm.created_at desc limit 20) t), '[]'::jsonb)),
    'refunds', jsonb_build_object(
        'count', (select count(*) from public.payment_refunds where status = 'succeeded'),
        'latest', coalesce((select jsonb_agg(x order by x->>'created_at' desc) from (
          select jsonb_build_object('user_id', pm.user_id, 'email', pr.email, 'currency', r.currency, 'amount_minor', r.amount_minor,
            'status', r.status, 'reason', r.reason, 'created_at', r.created_at, 'invoice', pm.provider_invoice_id) as x
          from public.payment_refunds r join public.payments pm on pm.id = r.payment_id
          left join public.profiles pr on pr.user_id = pm.user_id
          order by r.created_at desc limit 20) t), '[]'::jsonb))
  ) into v_out;
  return v_out;
end;
$$;
revoke all on function public.admin_revenue(jsonb) from public, anon;
grant execute on function public.admin_revenue(jsonb) to authenticated;

-- p: {action_prefix, target, page, page_size}
create or replace function public.admin_audit_list(p jsonb default '{}'::jsonb)
returns jsonb
language plpgsql stable security definer
set search_path = public
set jit = off                                    -- one-row reports: JIT compile time (seconds) >> run time (ms)
as $$
declare
  v_size int := least(greatest(coalesce((p->>'page_size')::int, 30), 5), 100);
  v_page int := greatest(coalesce((p->>'page')::int, 1), 1);
  v_act text := nullif(p->>'action_prefix', '');
  v_tgt uuid := nullif(p->>'target', '')::uuid;
  v_out jsonb;
begin
  perform public.kfp_require_admin('viewer');
  with f as (
    select l.*, count(*) over () as total from public.admin_audit_logs l
    where (v_act is null or l.action like replace(replace(v_act, '%', ''), '_', '\_') || '%')
      and (v_tgt is null or l.target_user_id = v_tgt)
    order by l.id desc limit v_size offset (v_page - 1) * v_size
  )
  select jsonb_build_object('page', v_page, 'page_size', v_size,
    'total', coalesce((select total from f limit 1), 0),
    'rows', coalesce((select jsonb_agg(jsonb_build_object('id', f.id, 'action', f.action, 'reason', f.reason, 'at', f.created_at,
        'admin', (select email from public.profiles where user_id = f.admin_id),
        'target_user_id', f.target_user_id, 'target', (select email from public.profiles where user_id = f.target_user_id),
        'before', f.before, 'after', f.after) order by f.id desc) from f), '[]'::jsonb))
  into v_out;
  return v_out;
end;
$$;
revoke all on function public.admin_audit_list(jsonb) from public, anon;
grant execute on function public.admin_audit_list(jsonb) to authenticated;

create or replace function public.admin_list_prices()
returns jsonb
language sql stable security definer
set search_path = public
as $$
